res.setHeader('Content-Security-Policy', getWebhookSandboxCSP());",The response handler uses the flawed HTML classification to decide whether to set the CSP sandbox header; a whitespace-prefixed MIME type skips this branch.,"{""code"":""	const contentTypeLower = contentType.toLowerCase();"",""desc"":""isHtmlRenderedContentType() 在 html-sandbox.ts 第 20 行仅对传入的 contentType 字符串执行 toLowerCase() 转换，生成 contentTypeLower，随后通过 startsWith 判断是否为 HTML 类型。由于此处跳过了 .trim() 步骤，任何含首尾空白的值在大小写规范化后依然保留空白前缀，致使 startsWith('text/html') 比较结果为 false，是整条漏洞链路的根因操作。"",""file"":""packages/core/src/html-sandbox.ts"",""line"":20}","{""code"":""		const contentType = res.getHeader('content-type') as string | undefined;
		const needsSandbox = !contentType || isHtmlRenderedContentType(contentType);

		if (needsSandbox && !isWebhookHtmlSandboxingDisabled()) {
			res.setHeader('Content-Security-Policy', getWebhookSandboxCSP());"",""desc"":""The response handler uses the flawed HTML classification to decide whether to set the CSP sandbox header; a whitespace-prefixed MIME type skips this branch."",""file"":""packages/cli/src/webhooks/webhook-request-handler.ts"",""line"":""153-157""}","Point at the real execution, security decision, or bypass-enabling operation instead of a wrapper, static declaration, or defensive helper definition."

res.setHeader('Content-Security-Policy', getWebhookSandboxCSP());",The false HTML classification makes needsSandbox false and suppresses the CSP sandbox header that would contain the response.,"[{""code"":""		}"",""desc"":""trace 链路的第 0 节点，以 webhook-helpers.ts 第 615 行的代码块闭合边界为锚点，代表 streaming 分支执行完毕后 runData 已持有 res 引用的起始状态。从此节点出发，调用栈向下游依次流经 setResponseHeaders() 与 isHtmlRenderedContentType()，是整条调用链的起始锚定点。"",""file"":""packages/cli/src/webhooks/webhook-helpers.ts"",""line"":615},{""code"":""
		if (responseMode === 'streaming') {
			Container.get(Logger).debug(
				`Execution of workflow ""${workflow.name}"" from with ID ${executionId} is set to streaming`,
				{ executionId },
			);
			// TODO: Add check for streaming nodes here
			runData.httpResponse = res;
			runData.streamingEnabled = true;
			didSendResponse = true;"",""desc"":""trace 第 1 步，位于 webhook-helpers.ts 第 605–614 行的 streaming 分支体内：responseMode 为 'streaming' 时，runData.httpResponse 被直接赋值为 res，runData.streamingEnabled 置为 true，didSendResponse 标记设为已响应。随后调用栈下游的 setResponseHeaders() 将以此 res 对象为操作目标，对用户指定的 headers 进行写入与读回。"",""file"":""packages/cli/src/webhooks/webhook-helpers.ts"",""line"":""605-614""},{""code"":""	private setResponseHeaders(res: express.Response, headers?: WebhookResponseHeaders) {
		if (headers) {
			for (const [name, value] of headers.entries()) {
				res.setHeader(name, value);
			}
		}

		const contentType = res.getHeader('content-type') as string | undefined;
		const needsSandbox = !contentType || isHtmlRenderedContentType(contentType);"",""desc"":""trace 第 2 步，setResponseHeaders() 位于 webhook-request-handler.ts 第 146–155 行，承接来自上游的 res 对象，将用户工作流指定的 headers 逐条通过 res.setHeader() 写入响应——含潜在首尾空白的 content-type 于此被设置。随后函数读回 content-type 头的当前值并调用 isHtmlRenderedContentType(contentType)，needsSandbox 的布尔结果决定是否追加 CSP sandbox 头，污染值由此传入检测函数。"",""file"":""packages/cli/src/webhooks/webhook-request-handler.ts"",""line"":""146-155""},{""code"":""export const isHtmlRenderedContentType = (contentType: string) => {
	const contentTypeLower = contentType.toLowerCase();

	return (
		// The content-type can also contain a charset, e.g. ""text/html; charset=utf-8""
		contentTypeLower.startsWith('text/html') || contentTypeLower.startsWith('application/xhtml+xml')
	);"",""desc"":""trace 第 3 步也是调用链终点，isHtmlRenderedContentType() 函数体位于 html-sandbox.ts 第 19–25 行，接收由 setResponseHeaders() 传入的 contentType 字符串。函数仅调用 toLowerCase() 生成 contentTypeLower，随即对 'text/html' 与 'application/xhtml+xml' 做 startsWith 前缀匹配。由于缺少 trim() 预处理，含首尾空白的 contentType 在大小写转换后仍无法通过前缀匹配，函数返回 false，上游 needsSandbox 判定失效，CSP 保护头被跳过。"",""file"":""packages/core/src/html-sandbox.ts"",""line"":""19-25""}]","[{""code"":""	const evaluatedHeaders =
		context.evaluateComplexWebhookDescriptionExpression<WebhookNodeResponseHeaders>(
			'responseHeaders',
		);
	if (evaluatedHeaders?.entries === undefined) {
		return headers;
	}

	for (const entry of evaluatedHeaders.entries) {
		headers.set(entry.name.toLowerCase(), entry.value);
	}"",""desc"":""The workflow-controlled responseHeaders values enter the response map without whitespace normalization."",""file"":""packages/cli/src/webhooks/webhook-helpers.ts"",""line"":""882-892""},{""code"":""		if (responseMode === 'onReceived' && !didSendResponse) {
			const responseBody = extractWebhookOnReceivedResponse(responseData, webhookResultData);
			const webhookResponse = createStaticResponse(responseBody, responseCode, responseHeaders);
			responseCallback(null, webhookResponse);"",""desc"":""The evaluated headers are packaged into the static webhook response returned to the common response handler."",""file"":""packages/cli/src/webhooks/webhook-helpers.ts"",""line"":""559-562""},{""code"":""		try {
			const response = await this.webhookManager.executeWebhook(req, res);

			// Modern way of responding to webhooks
			if (isWebhookResponse(response)) {
				await this.sendWebhookResponse(res, response);
			} else if (response.noWebhookResponse !== true) {
				// Legacy way of responding to webhooks. `WebhookResponse` should be used to
				// pass the response from the webhookManager. However, we still have code
				// that doesn't use that yet. We need to keep this here until all codepaths
				// return a `WebhookResponse` instead.
				this.sendLegacyResponse(res, response.data, true, response.responseCode, response.headers);"",""desc"":""The request handler receives the webhook result and forwards its attacker-controlled headers to the response-sending path."",""file"":""packages/cli/src/webhooks/webhook-request-handler.ts"",""line"":""65-76""},{""code"":""	private sendStaticResponse(res: express.Response, webhookResponse: WebhookStaticResponse) {
		const { body, code, headers } = webhookResponse;

		this.setResponseStatus(res, code);
		this.setResponseHeaders(res, headers);"",""desc"":""The static response branch extracts the headers and sends them to the shared header writer."",""file"":""packages/cli/src/webhooks/webhook-request-handler.ts"",""line"":""127-131""},{""code"":""	private setResponseHeaders(res: express.Response, headers?: WebhookResponseHeaders) {
		if (headers) {
			for (const [name, value] of headers.entries()) {
				res.setHeader(name, value);
			}"",""desc"":""The header writer copies the configured Content-Type value unchanged onto the Express response."",""file"":""packages/cli/src/webhooks/webhook-request-handler.ts"",""line"":""146-150""},{""code"":""export const isHtmlRenderedContentType = (contentType: string) => {
	const contentTypeLower = contentType.toLowerCase();

	return (
		// The content-type can also contain a charset, e.g. ""text/html; charset=utf-8""
		contentTypeLower.startsWith('text/html') || contentTypeLower.startsWith('application/xhtml+xml')
	);"",""desc"":""HTML classification lowercases but does not trim Content-Type, so a leading space makes the startsWith checks return false."",""file"":""packages/core/src/html-sandbox.ts"",""line"":""19-25""},{""code"":""		const contentType = res.getHeader('content-type') as string | undefined;
		const needsSandbox = !contentType || isHtmlRenderedContentType(contentType);

		if (needsSandbox && !isWebhookHtmlSandboxingDisabled()) {
			res.setHeader('Content-Security-Policy', getWebhookSandboxCSP());"",""desc"":""The false HTML classification makes needsSandbox false and suppresses the CSP sandbox header that would contain the response."",""file"":""packages/cli/src/webhooks/webhook-request-handler.ts"",""line"":""153-157""}]",Keep only the important data-flow or control-flow nodes from the entry point to the critical operation.

