		const returnValue = this.renderExpression(extendedExpression, data);"",""desc"":""The expression is syntax-expanded and passed to renderExpression."",""file"":""packages/workflow/src/expression.ts"",""line"":""506-507""},{""code"":""	private renderExpression(expression: string, data: IWorkflowDataProxyData) {
		// Use VM evaluator if engine is set to 'vm' and we're not in the browser
		if (Expression.expressionEngine === 'vm' && !IS_FRONTEND) {
