				);
			}

			try {
				const result = Expression.vmEvaluator.evaluate(expression, data, {
					timezone: this.timezone,
				});"",""desc"":""VM mode sends the transformed expression and workflow data into expression-runtime for evaluation."",""file"":""packages/workflow/src/expression.ts"",""line"":""524-536""},{""code"":""				path.replace(
					b.memberExpression(
